 function draw(canvas,enemy){if(!enemy.boss)return false;canvas.width=canvas.height=64;const ctx=canvas.getContext('2d'),p=GamePalette.tokens,colors={k:p.ink,d:p.dark,b:Craft.Types.color(enemy.types[0]),c:Craft.Types.color(enemy.types[1]||enemy.types[0]),m:p.metal,w:p.paper};ctx.clearRect(0,0,64,64);ctx.imageSmoothingEnabled=false;raster(enemy).forEach((color,i)=>{if(color){ctx.fillStyle=colors[color];ctx.fillRect(i%64,Math.floor(i/64),1,1);}});canvas.setAttribute('aria-label',enemy.name+' · '+(enemy.phase===1?'2':'1')+'페이즈 도트');return true;}
